{"cmd":"python - <<'PY'
import csv, math
from collections import defaultdict

def to_int(x):
    try: return int(float(x))
    except: return 0

def to_float(x):
    try: return float(x)
    except: return float('nan')

def phase(over):
    o=int(math.floor(over))
    if o<=5: return 'Powerplay'
    if o<=14: return 'Middle'
    return 'Death'

rows=[]
with open('benchmark/data.csv',newline='',encoding='utf-8') as f:
    reader=csv.DictReader(f)
    for r in reader:
        r['over']=to_float(r['over'])
        r['bowler']=(r.get('bowler','') or '').strip()
        r['wicket_type']=(r.get('wicket_type','') or '').strip()
        r['player_dismissed']=(r.get('player_dismissed','') or '').strip()
        for c in ['runs_of_bat','extras','wide','noballs']:
            r[c]=to_int(r[c])
        rows.append(r)

bph=defaultdict(lambda: {'runs':0,'balls':0,'wkts':0,'dots':0})
for r in rows:
    key=(r['bowler'], phase(r['over']))
    rec=bph[key]
    rec['runs']+=r['runs_of_bat']+r['extras']
    if r['wide']==0 and r['noballs']==0:
        rec['balls']+=1
        if r['runs_of_bat']==0 and r['extras']==0:
            rec['dots']+=1
    if r['wicket_type'] and r['player_dismissed']:
        rec['wkts']+=1

# find effective bowlers per phase: use wickets per over + economy, min 12 balls in phase
for ph in ['Powerplay','Middle','Death']:
    cand=[]
    for (b,p),rec in bph.items():
        if p!=ph or rec['balls']<12: continue
        overs=rec['balls']/6
        eco=rec['runs']/overs if overs else 0
        wpo=rec['wkts']/overs if overs else 0
        dot=rec['dots']/rec['balls']*100 if rec['balls'] else 0
        cand.append((wpo, -eco, dot, b, rec, eco))
    cand=sorted(cand, reverse=True)[:8]
    print(ph)
    for wpo,neco,dot,b,rec,eco in cand:
        print(' ',b,'balls',rec['balls'],'wkts',rec['wkts'],'eco',round(eco,2),'w/ov',round(wpo,2),'dot%',round(dot,1))

PY"}

