+
+    <script>
+      // Embedded computed aggregates (derived strictly from data.csv).
+      // Generated by a local script into output/report_data.json and pasted here.
+      const REPORT_DATA =
+        /*__REPORT_DATA__*/ null;
+
+      const fmt = {
+        num: (x, d = 0) =>
+          Number.isFinite(x)
+            ? x.toLocaleString(undefined, { maximumFractionDigits: d, minimumFractionDigits: d })
+            : "-",
+        pct: (x, d = 1) => `${fmt.num(x, d)}%`,
+      };
+
+      function el(tag, attrs = {}, children = []) {
+        const node = document.createElement(tag);
+        for (const [k, v] of Object.entries(attrs)) {
+          if (k === "class") node.className = v;
+          else if (k === "html") node.innerHTML = v;
+          else node.setAttribute(k, v);
+        }
+        for (const ch of children) node.appendChild(ch);
+        return node;
+      }
+
+      function clamp01(v) {
+        return Math.max(0, Math.min(1, v));
+      }
+
+      function setSvgText(svg, x, y, text, opts = {}) {
+        const t = document.createElementNS("http://www.w3.org/2000/svg", "text");
+        t.setAttribute("x", String(x));
+        t.setAttribute("y", String(y));
+        t.setAttribute("fill", opts.fill || "rgba(232, 238, 252, 0.92)");
+        t.setAttribute("font-size", String(opts.size || 12));
+        t.setAttribute("font-family", opts.font || "ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, Liberation Mono, Courier New, monospace");
+        if (opts.anchor) t.setAttribute("text-anchor", opts.anchor);
+        if (opts.weight) t.setAttribute("font-weight", String(opts.weight));
+        t.textContent = text;
+        svg.appendChild(t);
+        return t;
+      }
+
+      function setSvgRect(svg, x, y, w, h, opts = {}) {
+        const r = document.createElementNS("http://www.w3.org/2000/svg", "rect");
+        r.setAttribute("x", String(x));
+        r.setAttribute("y", String(y));
+        r.setAttribute("width", String(w));
+        r.setAttribute("height", String(h));
+        r.setAttribute("rx", String(opts.rx ?? 6));
+        r.setAttribute("fill", opts.fill || "rgba(99,179,255,0.85)");
+        if (opts.stroke) r.setAttribute("stroke", opts.stroke);
+        if (opts.strokeWidth) r.setAttribute("stroke-width", String(opts.strokeWidth));
+        svg.appendChild(r);
+        return r;
+      }
+
+      function clearSvg(svg) {
+        while (svg.firstChild) svg.removeChild(svg.firstChild);
+      }
+
+      function drawGrid(svg, chart, ticks = 4) {
+        const { x0, y0, w, h } = chart;
+        for (let i = 0; i <= ticks; i++) {
+          const y = y0 + (h * i) / ticks;
+          const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
+          line.setAttribute("x1", String(x0));
+          line.setAttribute("x2", String(x0 + w));
+          line.setAttribute("y1", String(y));
+          line.setAttribute("y2", String(y));
+          line.setAttribute("stroke", "rgba(255,255,255,0.10)");
+          line.setAttribute("stroke-width", "1");
+          svg.appendChild(line);
+        }
+      }
+
+      function barChart(svg, data, opts) {
+        // data: [{label, value, sublabel?, color?}]
+        clearSvg(svg);
+        const W = 900;
+        const H = svg.classList.contains("small") ? 260 : 320;
+        svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
+        const pad = { l: 170, r: 26, t: 20, b: 26 };
+        const chart = { x0: pad.l, y0: pad.t, w: W - pad.l - pad.r, h: H - pad.t - pad.b };
+        const maxV = Math.max(...data.map((d) => d.value), 1);
+        drawGrid(svg, chart, 4);
+
+        const rowH = chart.h / data.length;
+        for (let i = 0; i < data.length; i++) {
+          const d = data[i];
+          const y = chart.y0 + i * rowH + rowH * 0.18;
+          const bh = rowH * 0.64;
+          const bw = (d.value / maxV) * chart.w;
+          setSvgText(svg, pad.l - 12, y + bh * 0.72, d.label, {
+            size: 12,
+            anchor: "end",
+            font: "var(--sans)",
+          });
+          setSvgRect(svg, chart.x0, y, bw, bh, {
+            rx: 7,
+            fill: d.color || opts.color || "rgba(99,179,255,0.85)",
+          });
+          const valText = opts.format ? opts.format(d.value) : fmt.num(d.value, 1);
+          setSvgText(svg, chart.x0 + bw + 8, y + bh * 0.72, valText, {
+            size: 12,
+            font: "var(--mono)",
+          });
+          if (d.sublabel) {
+            setSvgText(svg, chart.x0 + 8, y + bh * 0.72, d.sublabel, {
+              size: 11,
+              font: "var(--mono)",
+              fill: "rgba(232, 238, 252, 0.80)",
+            });
+          }
+        }
+
+        if (opts.title) {
+          setSvgText(svg, 12, 18, opts.title, {
+            size: 14,
+            font: "var(--sans)",
+            weight: 700,
+          });
+        }
+      }
+
+      function groupedBarChart(svg, groups, opts) {
+        // groups: [{label, a, b, aLabel, bLabel}]
+        clearSvg(svg);
+        const W = 900;
+        const H = 320;
+        svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
+        const pad = { l: 230, r: 26, t: 20, b: 34 };
+        const chart = { x0: pad.l, y0: pad.t, w: W - pad.l - pad.r, h: H - pad.t - pad.b };
+        const maxV = Math.max(...groups.flatMap((g) => [g.a, g.b]), 1);
+        drawGrid(svg, chart, 4);
+
+        const rowH = chart.h / groups.length;
+        for (let i = 0; i < groups.length; i++) {
+          const g = groups[i];
+          const y0 = chart.y0 + i * rowH + rowH * 0.18;
+          const bh = rowH * 0.22;
+          const gap = rowH * 0.08;
+          setSvgText(svg, pad.l - 12, y0 + bh * 1.9, g.label, {
+            size: 12,
+            anchor: "end",
+            font: "var(--sans)",
+          });
+          const bwA = (g.a / maxV) * chart.w;
+          const bwB = (g.b / maxV) * chart.w;
+          setSvgRect(svg, chart.x0, y0, bwA, bh, { rx: 6, fill: opts.colorA || "rgba(99,179,255,0.85)" });
+          setSvgRect(svg, chart.x0, y0 + bh + gap, bwB, bh, { rx: 6, fill: opts.colorB || "rgba(124,255,166,0.70)" });
+          setSvgText(svg, chart.x0 + bwA + 8, y0 + bh * 0.78, opts.format ? opts.format(g.a) : fmt.num(g.a, 2), {
+            size: 11,
+          });
+          setSvgText(svg, chart.x0 + bwB + 8, y0 + (bh + gap) + bh * 0.78, opts.format ? opts.format(g.b) : fmt.num(g.b, 2), {
+            size: 11,
+          });
+        }
+
+        if (opts.title) {
+          setSvgText(svg, 12, 18, opts.title, {
+            size: 14,
+            font: "var(--sans)",
+            weight: 700,
+          });
+        }
+      }
+
+      function stackedBarChart(svg, data, keys, opts) {
+        // data: [{label, ...keys}]
+        clearSvg(svg);
+        const W = 900;
+        const H = 320;
+        svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
+        const pad = { l: 140, r: 26, t: 20, b: 34 };
+        const chart = { x0: pad.l, y0: pad.t, w: W - pad.l - pad.r, h: H - pad.t - pad.b };
+        const totals = data.map((d) => keys.reduce((s, k) => s + (d[k] || 0), 0));
+        const maxV = Math.max(...totals, 1);
+        drawGrid(svg, chart, 4);
+
+        const colors = opts.colors || [
+          "rgba(99,179,255,0.85)",
+          "rgba(124,255,166,0.70)",
+          "rgba(255,209,102,0.75)",
+          "rgba(255,122,122,0.75)",
+        ];
+
+        const rowH = chart.h / data.length;
+        for (let i = 0; i < data.length; i++) {
+          const d = data[i];
+          const y = chart.y0 + i * rowH + rowH * 0.20;
+          const bh = rowH * 0.60;
+          setSvgText(svg, pad.l - 12, y + bh * 0.72, d.label, {
+            size: 12,
+            anchor: "end",
+            font: "var(--sans)",
+          });
+          let x = chart.x0;
+          for (let k = 0; k < keys.length; k++) {
+            const key = keys[k];
+            const v = d[key] || 0;
+            const w = (v / maxV) * chart.w;
+            setSvgRect(svg, x, y, w, bh, { rx: 7, fill: colors[k] });
+            x += w;
+          }
+          const total = totals[i];
+          setSvgText(svg, chart.x0 + (total / maxV) * chart.w + 8, y + bh * 0.72, opts.format ? opts.format(total) : fmt.num(total, 0), {
+            size: 12,
+            font: "var(--mono)",
+          });
+        }
+
+        if (opts.title) {
+          setSvgText(svg, 12, 18, opts.title, {
+            size: 14,
+            font: "var(--sans)",
+            weight: 700,
+          });
+        }
+      }
+
+      function phaseLeaders(rows, phaseKey) {
+        // Compute leaders from ball-by-ball derived aggregates embedded in REPORT_DATA? Not available there.
+        // Instead, use heuristics based on overall leaderboards is insufficient.
+        // We'll compute phase-leaders in JS from a pre-embedded leaders list (added below).
+        return rows.filter((r) => r.phase === phaseKey);
+      }
+
+      function buildTable(tableId, rows, colDefs) {
+        const tbody = document.querySelector(`#${tableId} tbody`);
+        tbody.innerHTML = "";
+        for (const row of rows) {
+          const tr = document.createElement("tr");
+          for (const col of colDefs) {
+            const td = document.createElement("td");
+            const v = row[col.key];
+            td.className = col.className || "";
+            td.textContent = col.format ? col.format(v, row) : String(v);
+            tr.appendChild(td);
+          }
+          tbody.appendChild(tr);
+        }
+      }
+
+      function normalize(values) {
+        const min = Math.min(...values);
+        const max = Math.max(...values);
+        if (max - min < 1e-9) return values.map(() => 0.5);
+        return values.map((v) => (v - min) / (max - min));
+      }
+
+      function drawTeamRadar(svg, rows) {
+        // Not a radar in the strict sense; a compact normalized bar grid.
+        clearSvg(svg);
+        const W = 900;
+        const H = 260;
+        svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
+        const pad = { l: 80, r: 26, t: 26, b: 24 };
+        const chart = { x0: pad.l, y0: pad.t, w: W - pad.l - pad.r, h: H - pad.t - pad.b };
+
+        const top = rows.slice(0, 10);
+        const batRR = top.map((r) => r.bat_run_rate);
+        const bowlEco = top.map((r) => r.bowl_economy);
+        const bowlDot = top.map((r) => r.bowl_dot_pct);
+        const extras = top.map((r) => r.bowl_extras_conceded);
+
+        const nBat = normalize(batRR);
+        const nEco = normalize(bowlEco).map((v) => 1 - v); // invert
+        const nDot = normalize(bowlDot);
+        const nEx = normalize(extras).map((v) => 1 - v);
+
+        const cols = [
+          { key: "Bat RR", values: nBat, color: "rgba(99,179,255,0.85)" },
+          { key: "Bowl Econ", values: nEco, color: "rgba(124,255,166,0.70)" },
+          { key: "Bowl Dot%", values: nDot, color: "rgba(255,209,102,0.75)" },
+          { key: "Ex Discipline", values: nEx, color: "rgba(255,122,122,0.70)" },
+        ];
+
+        const rowH = chart.h / top.length;
+        const colW = chart.w / cols.length;
+        // headers
+        for (let c = 0; c < cols.length; c++) {
+          setSvgText(svg, chart.x0 + c * colW + colW / 2, 18, cols[c].key, {
+            size: 12,
+            anchor: "middle",
+            font: "var(--sans)",
+            fill: "rgba(169,182,211,0.95)",
+          });
+        }
+        for (let r = 0; r < top.length; r++) {
+          const y = chart.y0 + r * rowH + rowH * 0.20;
+          const bh = rowH * 0.60;
+          setSvgText(svg, 10, y + bh * 0.72, top[r].team, {
+            size: 12,
+            font: "var(--mono)",
+          });
+          for (let c = 0; c < cols.length; c++) {
+            const v = clamp01(cols[c].values[r]);
+            const x = chart.x0 + c * colW + 10;
+            const w = (colW - 20) * v;
+            setSvgRect(svg, x, y, w, bh, { rx: 6, fill: cols[c].color });
+            setSvgRect(svg, x + w, y, (colW - 20) - w, bh, { rx: 6, fill: "rgba(255,255,255,0.05)" });
+          }
+        }
+      }
+
+      function main() {
+        const data = REPORT_DATA;
+        if (!data) {
+          document.body.innerHTML = "<pre>Report data missing.</pre>";
+          return;
+        }
+
+        // KPI dashboard
+        const kpiGrid = document.getElementById("kpiGrid");
+        const kpiMeta = [
+          {
+            name: "Average Runs Per Over",
+            fmt: (v) => fmt.num(v, 2),
+            note: "Total (bat+extras) / legal overs",
+          },
+          {
+            name: "Boundary Percentage",
+            fmt: (v) => fmt.pct(v, 2),
+            note: "% deliveries with 4 or 6",
+          },
+          {
+            name: "Dot Ball Percentage",
+            fmt: (v) => fmt.pct(v, 2),
+            note: "% deliveries with 0 + 0 extras",
+          },
+          {
+            name: "Extras Per Match",
+            fmt: (v) => fmt.num(v, 2),
+            note: "Mean extras across matches",
+          },
+          {
+            name: "Wickets Per Match",
+            fmt: (v) => fmt.num(v, 2),
+            note: "Mean wickets across matches",
+          },
+        ];
+        for (const k of kpiMeta) {
+          const v = data.kpis[k.name];
+          const card = el("div", { class: "card" }, [
+            el("p", { class: "kpi-name", html: k.name }),
+            el("div", { class: "kpi-value" }, [document.createTextNode(k.fmt(v))]),
+            el("div", { class: "kpi-note" }, [document.createTextNode(k.note)]),
+          ]);
+          kpiGrid.appendChild(card);
+        }
+        document.getElementById("kpiFootnote").textContent =
+          `Coverage: ${data.meta.matches} matches, ${data.meta.deliveries.toLocaleString()} deliveries, ${data.meta.teams} teams, ${data.meta.venues} venues (from ${data.meta.date_start} to ${data.meta.date_end}).`;
+
+        // Overview callouts
+        const overview = document.getElementById("overviewPills");
+        const totals = {
+          matches: data.meta.matches,
+          deliveries: data.meta.deliveries,
+          venues: data.meta.venues,
+          teams: data.meta.teams,
+          boundaryPct: data.kpis["Boundary Percentage"],
+          dotPct: data.kpis["Dot Ball Percentage"],
+        };
+        const calls = [
+          { label: "Matches", value: fmt.num(totals.matches, 0) },
+          { label: "Deliveries", value: fmt.num(totals.deliveries, 0) },
+          { label: "Teams", value: fmt.num(totals.teams, 0) },
+          { label: "Venues", value: fmt.num(totals.venues, 0) },
+          { label: "Boundary%", value: fmt.pct(totals.boundaryPct, 2) },
+          { label: "Dot%", value: fmt.pct(totals.dotPct, 2) },
+        ];
+        for (const c of calls) {
+          overview.appendChild(
+            el("div", { class: "call" }, [
+              el("div", { class: "label" }, [document.createTextNode(c.label)]),
+              el("div", { class: "value" }, [document.createTextNode(c.value)]),
+            ])
+          );
+        }
+        document.getElementById("dataCoverageNote").textContent =
+          "Dataset is a partial-season snapshot; interpret ranks/means in that context.";
+
+        // Phase chart: dual metric (RPO and run share)
+        const phaseRows = data.phase_summary;
+        const totalPhaseRuns = phaseRows.reduce((s, r) => s + r.runs, 0);
+        const phaseForChart = phaseRows.map((r) => ({
+          label: r.phase,
+          value: r.rpo,
+          share: totalPhaseRuns ? (r.runs / totalPhaseRuns) : 0,
+        }));
+        // draw custom dual-bar in one svg
+        const phaseSvg = document.getElementById("phaseRunsChart");
+        clearSvg(phaseSvg);
+        phaseSvg.setAttribute("viewBox", "0 0 900 320");
+        const pad = { l: 170, r: 26, t: 26, b: 26 };
+        const chart = { x0: pad.l, y0: pad.t, w: 900 - pad.l - pad.r, h: 320 - pad.t - pad.b };
+        drawGrid(phaseSvg, chart, 4);
+        const maxRPO = Math.max(...phaseForChart.map((d) => d.value), 1);
+        const rowH = chart.h / phaseForChart.length;
+        for (let i = 0; i < phaseForChart.length; i++) {
+          const d = phaseForChart[i];
+          const y = chart.y0 + i * rowH + rowH * 0.22;
+          const bh = rowH * 0.22;
+          const gap = rowH * 0.10;
+          setSvgText(phaseSvg, pad.l - 12, y + bh * 0.85 + bh + gap * 0.55, d.label, {
+            size: 12,
+            anchor: "end",
+            font: "var(--sans)",
+          });
+          const wR = (d.value / maxRPO) * chart.w;
+          const wS = d.share * chart.w;
+          setSvgRect(phaseSvg, chart.x0, y, wR, bh, { rx: 6, fill: "rgba(99,179,255,0.85)" });
+          setSvgRect(phaseSvg, chart.x0, y + bh + gap, wS, bh, { rx: 6, fill: "rgba(124,255,166,0.70)" });
+          setSvgText(phaseSvg, chart.x0 + wR + 8, y + bh * 0.85, `RPO ${fmt.num(d.value, 2)}`, { size: 11 });
+          setSvgText(phaseSvg, chart.x0 + wS + 8, y + bh + gap + bh * 0.85, `Run share ${fmt.pct(d.share * 100, 1)}`, { size: 11 });
+        }
+        setSvgText(phaseSvg, 12, 18, "Scoring by phase: run rate + run share", {
+          size: 14,
+          font: "var(--sans)",
+          weight: 700,
+        });
+
+        // Dismissal chart
+        const dismissals = data.dismissal_types.slice(0, 8);
+        barChart(
+          document.getElementById("dismissalChart"),
+          dismissals.map((d) => ({ label: d.type, value: d.count })),
+          {
+            title: "Dismissal types (top 8)",
+            format: (v) => fmt.num(v, 0),
+            color: "rgba(255,209,102,0.78)",
+          }
+        );
+
+        // Batting charts
+        const topRuns = data.batting.top_runs;
+        barChart(
+          document.getElementById("topBattersRuns"),
+          topRuns.map((r) => ({
+            label: r.striker,
+            value: r.runs,
+            sublabel: `SR ${fmt.num(r.sr, 1)}  |  4s ${r["4s"]}  6s ${r["6s"]}`,
+          })),
+          { title: "Top run-scorers (runs off the bat)", format: (v) => fmt.num(v, 0) }
+        );
+
+        const topSR = data.batting.top_sr_min30;
+        barChart(
+          document.getElementById("topBattersSR"),
+          topSR.map((r) => ({
+            label: r.striker,
+            value: r.sr,
+            sublabel: `${fmt.num(r.runs, 0)} runs / ${fmt.num(r.balls, 0)} balls`,
+            color: "rgba(124,255,166,0.70)",
+          })),
+          { title: "Highest strike rates (min 30 balls)", format: (v) => fmt.num(v, 1), color: "rgba(124,255,166,0.70)" }
+        );
+
+        // Phase boundary vs dot (grouped)
+        const phaseBD = data.phase_summary.map((p) => ({
+          label: p.phase,
+          a: p.boundary_pct,
