+    <script>
+      // Embedded computed aggregates (derived strictly from data.csv).
+      // Generated by a local script into output/report_data.json and pasted here.
+      const REPORT_DATA =
+        /*__REPORT_DATA__*/ null;
+
+      const fmt = {
+        num: (x, d = 0) =>
+          Number.isFinite(x)
+            ? x.toLocaleString(undefined, { maximumFractionDigits: d, minimumFractionDigits: d })
+            : "-",
+        pct: (x, d = 1) => `${fmt.num(x, d)}%`,
+      };
+
+      function el(tag, attrs = {}, children = []) {
+        const node = document.createElement(tag);
+        for (const [k, v] of Object.entries(attrs)) {
+          if (k === "class") node.className = v;
+          else if (k === "html") node.innerHTML = v;
+          else node.setAttribute(k, v);
+        }
+        for (const ch of children) node.appendChild(ch);
+        return node;
+      }
+
+      function clamp01(v) {
+        return Math.max(0, Math.min(1, v));
+      }
+
+      function setSvgText(svg, x, y, text, opts = {}) {
+        const t = document.createElementNS("http://www.w3.org/2000/svg", "text");
+        t.setAttribute("x", String(x));
+        t.setAttribute("y", String(y));
+        t.setAttribute("fill", opts.fill || "rgba(232, 238, 252, 0.92)");
+        t.setAttribute("font-size", String(opts.size || 12));
+        t.setAttribute("font-family", opts.font || "ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, Liberation Mono, Courier New, monospace");
+        if (opts.anchor) t.setAttribute("text-anchor", opts.anchor);
+        if (opts.weight) t.setAttribute("font-weight", String(opts.weight));
+        t.textContent = text;
+        svg.appendChild(t);
+        return t;
+      }
+
+      function setSvgRect(svg, x, y, w, h, opts = {}) {
+        const r = document.createElementNS("http://www.w3.org/2000/svg", "rect");
+        r.setAttribute("x", String(x));
+        r.setAttribute("y", String(y));
+        r.setAttribute("width", String(w));
+        r.setAttribute("height", String(h));
+        r.setAttribute("rx", String(opts.rx ?? 6));
+        r.setAttribute("fill", opts.fill || "rgba(99,179,255,0.85)");
+        if (opts.stroke) r.setAttribute("stroke", opts.stroke);
+        if (opts.strokeWidth) r.setAttribute("stroke-width", String(opts.strokeWidth));
+        svg.appendChild(r);
+        return r;
+      }
+
+      function clearSvg(svg) {
+        while (svg.firstChild) svg.removeChild(svg.firstChild);
+      }
+
+      function drawGrid(svg, chart, ticks = 4) {
+        const { x0, y0, w, h } = chart;
+        for (let i = 0; i <= ticks; i++) {
+          const y = y0 + (h * i) / ticks;
+          const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
+          line.setAttribute("x1", String(x0));
+          line.setAttribute("x2", String(x0 + w));
+          line.setAttribute("y1", String(y));
+          line.setAttribute("y2", String(y));
+          line.setAttribute("stroke", "rgba(255,255,255,0.10)");
+          line.setAttribute("stroke-width", "1");
+          svg.appendChild(line);
+        }
+      }
+
+      function barChart(svg, data, opts) {
+        // data: [{label, value, sublabel?, color?}]
+        clearSvg(svg);
+        const W = 900;
+        const H = svg.classList.contains("small") ? 260 : 320;
+        svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
+        const pad = { l: 170, r: 26, t: 20, b: 26 };
+        const chart = { x0: pad.l, y0: pad.t, w: W - pad.l - pad.r, h: H - pad.t - pad.b };
+        const maxV = Math.max(...data.map((d) => d.value), 1);
+        drawGrid(svg, chart, 4);
+
+        const rowH = chart.h / data.length;
+        for (let i = 0; i < data.length; i++) {
+          const d = data[i];
+          const y = chart.y0 + i * rowH + rowH * 0.18;
+          const bh = rowH * 0.64;
+          const bw = (d.value / maxV) * chart.w;
+          setSvgText(svg, pad.l - 12, y + bh * 0.72, d.label, {
+            size: 12,
+            anchor: "end",
+            font: "var(--sans)",
+          });
+          setSvgRect(svg, chart.x0, y, bw, bh, {
+            rx: 7,
+            fill: d.color || opts.color || "rgba(99,179,255,0.85)",
+          });
+          const valText = opts.format ? opts.format(d.value) : fmt.num(d.value, 1);
+          setSvgText(svg, chart.x0 + bw + 8, y + bh * 0.72, valText, {
+            size: 12,
+            font: "var(--mono)",
+          });
+          if (d.sublabel) {
+            setSvgText(svg, chart.x0 + 8, y + bh * 0.72, d.sublabel, {
+              size: 11,
+              font: "var(--mono)",
+              fill: "rgba(232, 238, 252, 0.80)",
+            });
+          }
+        }
+
+        if (opts.title) {
+          setSvgText(svg, 12, 18, opts.title, {
+            size: 14,
+            font: "var(--sans)",
+            weight: 700,
+          });
+        }
+      }
+
+      function groupedBarChart(svg, groups, opts) {
+        // groups: [{label, a, b, aLabel, bLabel}]
+        clearSvg(svg);
+        const W = 900;
+        const H = 320;
+        svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
+        const pad = { l: 230, r: 26, t: 20, b: 34 };
