+          const bh = rowH * 0.22;
+          const gap = rowH * 0.08;
+          setSvgText(svg, pad.l - 12, y0 + bh * 1.9, g.label, {
+            size: 12,
+            anchor: "end",
+            font: "var(--sans)",
+          });
+          const bwA = (g.a / maxV) * chart.w;
+          const bwB = (g.b / maxV) * chart.w;
+          setSvgRect(svg, chart.x0, y0, bwA, bh, { rx: 6, fill: opts.colorA || "rgba(99,179,255,0.85)" });
+          setSvgRect(svg, chart.x0, y0 + bh + gap, bwB, bh, { rx: 6, fill: opts.colorB || "rgba(124,255,166,0.70)" });
+          setSvgText(svg, chart.x0 + bwA + 8, y0 + bh * 0.78, opts.format ? opts.format(g.a) : fmt.num(g.a, 2), {
+            size: 11,
+          });
+          setSvgText(svg, chart.x0 + bwB + 8, y0 + (bh + gap) + bh * 0.78, opts.format ? opts.format(g.b) : fmt.num(g.b, 2), {
+            size: 11,
+          });
+        }
+
+        if (opts.title) {
+          setSvgText(svg, 12, 18, opts.title, {
+            size: 14,
+            font: "var(--sans)",
+            weight: 700,
+          });
+        }
+      }
+
+      function stackedBarChart(svg, data, keys, opts) {
+        // data: [{label, ...keys}]
+        clearSvg(svg);
+        const W = 900;
+        const H = 320;
+        svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
+        const pad = { l: 140, r: 26, t: 20, b: 34 };
+        const chart = { x0: pad.l, y0: pad.t, w: W - pad.l - pad.r, h: H - pad.t - pad.b };
+        const totals = data.map((d) => keys.reduce((s, k) => s + (d[k] || 0), 0));
+        const maxV = Math.max(...totals, 1);
+        drawGrid(svg, chart, 4);
+
+        const colors = opts.colors || [
+          "rgba(99,179,255,0.85)",
+          "rgba(124,255,166,0.70)",
+          "rgba(255,209,102,0.75)",
+          "rgba(255,122,122,0.75)",
+        ];
+
+        const rowH = chart.h / data.length;
+        for (let i = 0; i < data.length; i++) {
+          const d = data[i];
+          const y = chart.y0 + i * rowH + rowH * 0.20;
+          const bh = rowH * 0.60;
+          setSvgText(svg, pad.l - 12, y + bh * 0.72, d.label, {
+            size: 12,
+            anchor: "end",
+            font: "var(--sans)",
+          });
+          let x = chart.x0;
+          for (let k = 0; k < keys.length; k++) {
+            const key = keys[k];
+            const v = d[key] || 0;
+            const w = (v / maxV) * chart.w;
+            setSvgRect(svg, x, y, w, bh, { rx: 7, fill: colors[k] });
+            x += w;
+          }
+          const total = totals[i];
+          setSvgText(svg, chart.x0 + (total / maxV) * chart.w + 8, y + bh * 0.72, opts.format ? opts.format(total) : fmt.num(total, 0), {
+            size: 12,
+            font: "var(--mono)",
+          });
+        }
+
+        if (opts.title) {
+          setSvgText(svg, 12, 18, opts.title, {
+            size: 14,
+            font: "var(--sans)",
+            weight: 700,
+          });
+        }
+      }
+
+      function phaseLeaders(rows, phaseKey) {
