+        const pad = { l: 80, r: 26, t: 26, b: 24 };
+        const chart = { x0: pad.l, y0: pad.t, w: W - pad.l - pad.r, h: H - pad.t - pad.b };
+
+        const top = rows.slice(0, 10);
+        const batRR = top.map((r) => r.bat_run_rate);
